<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { profileRequest } from '../api'

const data=ref<any>(null),busy=ref(false),error=ref(''),platform=ref(''),region=ref(''),search=ref(''),page=ref(1)
const configOpen=ref(false),providerOpen=ref(false),detailOpen=ref(false),selected=ref<any>(null),history=ref<any>(null)
const settings=reactive({enabled:false,refreshHours:24,transport:'web-http',revision:0})
const provider=reactive({provider:'appfigures',accountLabel:'',apiKey:'',clearKey:false,licensed:false,revision:0})
let sequence=0,timer:ReturnType<typeof setInterval>|undefined
const api=(path='',method='GET',body?:unknown)=>profileRequest('/api/v1/admin/capture-workspace/metrics'+path,{method,...(body?{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})})
async function refresh(){const n=++sequence;try{const q=new URLSearchParams({platform:platform.value,region:region.value,search:search.value,page:String(page.value)});const value=await api('?'+q);if(n===sequence){data.value=value;page.value=value.page;error.value=''}}catch(e:any){if(n===sequence)error.value=e.message||'加载失败'}}
async function guard(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await action()}catch(e:any){error.value=e.message||'操作失败'}finally{busy.value=false}}
function filter(){page.value=1;void refresh()}
const time=(v:any)=>v?new Date(/(?:Z|[+-]\d\d:\d\d)$/.test(String(v))?String(v):String(v)+'Z').toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未提供'
const status=(v:string)=>({PENDING:'等待补全',RUNNING:'补全中',SUCCEEDED:'采集成功',FAILED:'采集失败',CANCELLED:'来源已停用'}[v]||v)
const platformName=(v:string)=>({IOS:'iOS',GOOGLE_PLAY:'Google Play',WECHAT:'微信小游戏',DOUYIN:'抖音小游戏'}[v]||v)
const method=(v:string)=>({OFFICIAL_DISPLAY:'官方展示',STORE_RANGE:'官方下载档位',THIRD_PARTY_ESTIMATE:'第三方估算'}[v]||v)
const metricName=(v:string)=>({price:'售价',rating:'评分',rating_count:'评分数量',installs:'累计下载档位',has_iap:'含内购',contains_ads:'含广告'}[v]||v)
const periodName=(v:string)=>({AT_CAPTURE:'抓取时展示值',LIFETIME:'历史累计'}[v]||v)
const scopeName=(v:string)=>({GLOBAL:'全球',cn:'中国',us:'美国',gb:'英国',de:'德国',fr:'法国'}[v]||v)
const sourceName=(v:string)=>({'apple-lookup':'Apple 官方接口','apple-detail':'App Store 详情','google-detail':'Google Play 详情'}[v]||v)
const counts=computed(()=>Object.fromEntries((data.value?.jobCounts||[]).map((r:any)=>[r.status,r.count])))
function latest(row:any,key:string){return [...(row.jobs||[])].filter(j=>j.snapshot?.metrics?.some((m:any)=>m.key===key)).sort((a,b)=>String(b.captured_at).localeCompare(String(a.captured_at))).map(j=>({job:j,value:j.snapshot.metrics.find((m:any)=>m.key===key)}))[0]}
function price(row:any){const v=latest(row,'price');return v?`${v.value.currency} ${v.value.rawDisplay}`:row.existing?.priceRaw?.label||'未知'}
function installs(row:any){return latest(row,'installs')?.value.rawDisplay||row.existing?.installsDisplay||'未知'}
function flag(row:any,key:string){return latest(row,key)?'已标注':'未知'}
function open(row:any){selected.value=row;history.value=null;detailOpen.value=true}
function configure(){const c=data.value.config;Object.assign(settings,{enabled:c.enabled,refreshHours:c.refresh_hours,transport:c.transport,revision:c.revision});configOpen.value=true}
async function saveConfig(){await guard(async()=>{await api('/config','PUT',settings);configOpen.value=false;await refresh();ElMessage.success('补全计划已保存')})}
async function enqueue(row?:any){await guard(async()=>{const r=await api('/enqueue','POST',row?{platform:row.platform,externalId:row.external_id,region:row.region}:{});ElMessage.success(`已排队 ${r.queued} 项；缓存或处理中 ${r.cachedOrPending} 项`);await refresh()})}
async function showHistory(id:string){await guard(async()=>{history.value=await api('/jobs/'+id)})}
function editProvider(p:any){Object.assign(provider,{provider:p.provider,accountLabel:p.account_label,apiKey:'',clearKey:false,licensed:p.licensed,revision:p.revision});providerOpen.value=true}
async function saveProvider(){await guard(async()=>{await api('/providers/'+provider.provider,'PUT',provider);provider.apiKey='';providerOpen.value=false;await refresh();ElMessage.success('配置已保存，授权数据仍待验证，未调用收费接口')})}
function download(){const contents=history.value||selected.value;const u=URL.createObjectURL(new Blob([JSON.stringify(contents,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='game-metrics-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
onMounted(()=>{void refresh();timer=setInterval(()=>{if(!document.hidden&&!busy.value)void refresh()},15000)})
onUnmounted(()=>{sequence++;if(timer)clearInterval(timer)})
</script>
<template>
<div class="game-metrics">
 <div class="heading"><div><h2>榜单游戏 · 下载与付费信息</h2><p>按平台游戏 ID 补充商店详情。售价、下载档位与估算分别展示，未知数据保持未知。</p></div><div class="actions"><el-button :disabled="busy" @click="refresh">刷新指标</el-button><el-button :disabled="busy||!data" @click="configure">补全设置</el-button><el-button type="primary" :loading="busy" @click="enqueue()">补全全部榜内游戏</el-button></div></div>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <template v-if="data">
 <div class="summary"><span>最新榜内去重 <b>{{data.rankedGames}}</b> 个平台/地区游戏</span><span>等待 {{counts.PENDING||0}} · 处理中 {{counts.RUNNING||0}} · 成功 {{counts.SUCCEEDED||0}} · 失败 {{counts.FAILED||0}}</span><span>{{data.config.enabled?'自动补全已启用':'自动补全未启用'}} · {{data.config.workerOnline?'执行器在线':'执行器离线 / 尚无心跳'}}</span><span>海外最近领取：{{time(data.config.remote_seen_at)}}</span></div>
 <el-alert title="售价不是流水。AppBrain近30日安装为估算，榜单国家不代表该数字只统计此国。微信/抖音新增用户、活跃和付费人数没有公开值时不填0，也不套用同名App数据。" type="info" :closable="false"/>
 <div class="filters"><el-select v-model="platform" placeholder="全部平台" clearable @change="filter"><el-option v-for="p in ['IOS','GOOGLE_PLAY','WECHAT','DOUYIN']" :key="p" :value="p" :label="platformName(p)"/></el-select><el-select v-model="region" placeholder="全部商店地区" clearable @change="filter"><el-option v-for="r in ['cn','us','gb','de','fr']" :key="r" :value="r" :label="r.toUpperCase()"/></el-select><el-input v-model="search" clearable placeholder="游戏名称、商店ID、开发者" @keyup.enter="filter" @clear="filter"/><el-button @click="filter">搜索</el-button></div>
 <el-table :data="data.rows" stripe row-key="identity">
  <el-table-column label="游戏 / 平台身份" min-width="220"><template #default="{row}"><b>{{row.name}}</b><p>{{platformName(row.platform)}} · {{row.region.toUpperCase()}}</p><small>{{row.external_id}}</small><p class="muted">{{row.rankings.map((r:any)=>`${r.chart} #${r.rank}`).join(' / ')}}</p></template></el-table-column>
  <el-table-column label="售价 / 内购" min-width="160"><template #default="{row}"><b>{{price(row)}}</b><p>内购：{{flag(row,'has_iap')}}</p><p>含广告：{{flag(row,'contains_ads')}}</p><small>售价不是收入</small></template></el-table-column>
  <el-table-column label="累计下载 / 近30日" min-width="200"><template #default="{row}"><b>{{installs(row)}}</b><p>{{latest(row,'installs')?'Google官方累计档位':row.existing?.installsDisplay?'AppBrain安装展示原文':'无公开下载值'}}</p><p>30日估算：{{row.existing?.recentInstallsDisplay||'未知'}}</p><small>地域范围见证据；不是日下载</small></template></el-table-column>
  <el-table-column label="收入 / 付费人数" min-width="160"><template #default="{row}"><span>未知</span><p class="muted">{{row.supported?'尚无授权估算数据':'需对应小游戏公开数据或后台授权'}}</p></template></el-table-column>
  <el-table-column label="补全进度" min-width="210"><template #default="{row}"><div v-for="j in row.jobs" :key="j.id" class="job"><span>{{sourceName(j.source_key)}} · {{status(j.status)}}</span><small v-if="j.error_code">{{j.error_code}}；旧值保留</small><small v-if="j.captured_at">{{time(j.captured_at)}} {{j.stale?'· 已过缓存期':''}}</small></div><span v-if="!row.jobs.length">{{row.supported?'尚未补全':'缺少公开指标，保持未知'}}</span></template></el-table-column>
  <el-table-column label="操作" width="120" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">详情与证据</el-button><el-button v-if="row.supported" link type="primary" :disabled="busy" @click="enqueue(row)">排队补全</el-button></template></el-table-column>
 </el-table>
 <el-pagination v-model:current-page="page" :page-size="20" :total="data.total" layout="prev, pager, next, total" @current-change="refresh"/>
 <details class="providers"><summary>下载 / 收入估算源接入配置</summary><p>尚无付费账号；以下配置仅为后续授权接入准备。保存Key不会调用收费接口，也不代表供应商已验证。收入范围需逐源确认，内购净收入不能当IAA广告收入。</p><div class="provider" v-for="p in data.providers" :key="p.provider"><b>{{p.provider}}</b><span>{{p.keyConfigured?'已保存Key':'未配置Key'}} · {{p.licensed?'已声明授权，待验证':'尚无API授权'}}</span><a :href="p.url" target="_blank" rel="noopener noreferrer">来源说明 ↗</a><el-button link type="primary" @click="editProvider(p)">配置接入</el-button></div></details>
 </template>
 <el-dialog v-model="configOpen" title="商店指标补全设置" width="min(600px,94vw)"><el-form label-position="top"><el-form-item label="自动发现最新启用榜单中的游戏"><el-switch v-model="settings.enabled"/></el-form-item><el-form-item label="成功数据刷新间隔"><el-select v-model="settings.refreshHours"><el-option v-for="h in [24,48,72]" :key="h" :value="h" :label="`${h}小时`"/></el-select></el-form-item><el-form-item label="服务器商店详情获取工具"><el-select v-model="settings.transport"><el-option value="web-http" label="普通HTTPS网页"/><el-option value="firecrawl" label="Firecrawl（需已启用服务）"/></el-select></el-form-item></el-form><p>独立执行器顺序补全，缓存期内去重，失败后退避6小时。关闭自动发现不会撤回已排队任务；停用来源后待处理任务取消。原榜单08:30、23:00计划保持独立。Google Play详情由海外执行器获取；下载档位不能推算精确日下载。</p><template #footer><el-button @click="configOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveConfig">保存补全设置</el-button></template></el-dialog>
 <el-dialog v-model="providerOpen" title="授权数据商接入准备" width="min(600px,94vw)" @closed="provider.apiKey=''"><el-form label-position="top"><el-form-item label="供应商"><el-input :model-value="provider.provider" disabled/></el-form-item><el-form-item label="账号备注（不填密码）"><el-input v-model="provider.accountLabel" maxlength="200"/></el-form-item><el-form-item label="API Key（留空保留，服务器加密保存）"><el-input v-model="provider.apiKey" type="password" autocomplete="new-password"/></el-form-item><el-checkbox v-model="provider.clearKey">清空已保存Key</el-checkbox><el-checkbox v-model="provider.licensed">已取得该供应商API授权</el-checkbox></el-form><p>状态仍为待验证，不会自动调用收费API。接入前还需验证榜内游戏覆盖、ID映射、套餐和收入统计口径。</p><template #footer><el-button @click="providerOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveProvider">保存接入配置</el-button></template></el-dialog>
 <el-drawer v-model="detailOpen" title="游戏指标 · 来源与历史" size="min(1100px,96vw)">
  <template v-if="selected"><h2>{{selected.name}}</h2><p>{{platformName(selected.platform)}} · {{selected.region}} · {{selected.external_id}}</p><el-button @click="download">下载当前证据JSON</el-button><h3>原榜单已有数据</h3><p>来源日 {{selected.businessDate||'未知'}} · 采集 {{time(selected.capturedAt)}} · 观察 #{{selected.observationId}}</p><a :href="selected.source_url" target="_blank" rel="noopener noreferrer">原榜单来源 ↗</a><p class="muted">AppBrain安装展示原文/30日估算不自动继承榜单国家；价格为所在商店售价。</p><pre>{{JSON.stringify(selected.existing,null,2)}}</pre><p class="hash">原材料SHA256：{{selected.raw_sha256}}</p>
  <template v-for="j in selected.jobs" :key="j.id"><h3>{{sourceName(j.source_key)}} · {{status(j.status)}}</h3><el-alert v-if="j.error_code" :title="`${j.error_code}；保留上次成功数据`" type="warning" :closable="false"/><template v-if="j.snapshot"><a :href="j.snapshot.sourceUrl" target="_blank" rel="noopener noreferrer">详情来源 ↗</a><p>{{time(j.snapshot.capturedAt)}} {{j.stale?'· 已过缓存期':''}}</p><el-table :data="j.snapshot.metrics" stripe><el-table-column label="指标" min-width="130"><template #default="{row}">{{metricName(row.key)}}</template></el-table-column><el-table-column prop="rawDisplay" label="来源原文" min-width="130"/><el-table-column label="口径" min-width="130"><template #default="{row}">{{method(row.method)}}</template></el-table-column><el-table-column label="指标地域" width="100"><template #default="{row}">{{scopeName(row.geographicScope)}}</template></el-table-column><el-table-column label="统计周期" min-width="130"><template #default="{row}">{{periodName(row.period)}}</template></el-table-column><el-table-column prop="currency" label="币种" width="80"/></el-table><template v-if="j.snapshot.purchases.length"><h4>页面展示内购商品（不保证完整）</h4><el-table :data="j.snapshot.purchases" stripe><el-table-column prop="name" label="名称"/><el-table-column prop="priceDisplay" label="展示价格"/></el-table></template><p v-for="note in j.snapshot.limitations" :key="note" class="muted">{{note}}</p><p class="hash">SHA256：{{j.snapshot.rawSha256}}</p></template><el-button :disabled="busy" @click="showHistory(j.id)">查看该来源历史</el-button></template>
  <el-empty v-if="!selected.jobs.length" :description="selected.supported?'尚无详情观察，可排队补全':'小游戏未取得对应指标；不会将同名App数据混入'"/>
  <template v-if="history"><h3>来源历史（最近30次）</h3><p>下次可请求：{{time(history.job.due_at)}} · 尝试 {{history.job.attempts}} 次</p><details v-for="o in history.observations" :key="o.id"><summary>{{time(o.captured_at)}} · {{o.id}}</summary><pre>{{JSON.stringify(o.snapshot_json,null,2)}}</pre></details></template></template>
 </el-drawer>
</div>
</template>
<style scoped>
.heading,.actions,.summary,.filters,.provider{display:flex;gap:14px;align-items:center;flex-wrap:wrap}.heading{justify-content:space-between;margin:18px 0}.heading h2{font-size:20px;margin:0 0 8px}.heading p,.muted,small{font-size:12px;color:#718096;line-height:1.7}.summary{padding:14px 0;font-size:13px}.filters{margin:20px 0}.filters .el-select{width:170px}.filters .el-input{width:270px}.game-metrics p{margin:6px 0}.job{margin:7px 0;font-size:12px}.job small{display:block}.el-pagination{margin:20px 0}.providers{border-top:1px solid #e2e8ef;padding:20px 0}.providers summary,summary{cursor:pointer;color:#336caa}.provider{padding:14px 0;border-bottom:1px solid #eef1f4;font-size:13px}.provider b{width:100px}a{color:#336caa}.hash,pre{overflow-wrap:anywhere}pre{white-space:pre-wrap;background:#f5f7fa;padding:14px;font-size:12px}.game-metrics :deep(.cell){word-break:normal;overflow-wrap:anywhere}.actions .el-button{margin:0}.el-checkbox{max-width:100%}@media(max-width:650px){.filters .el-select{width:145px}.filters .el-input{width:100%}.heading{align-items:flex-start}.el-pagination{overflow:auto}.summary{align-items:flex-start;flex-direction:column}}
</style>
